mapper.select:
SELECT l.*, r.name AS rule_name, s.name AS store_name, c.name AS campaign_name, u.nickname AS applied_by_name
FROM ecom_ad_rule_log l
JOIN ecom_store s ON s.id = l.store_id
LEFT JOIN ecom_ad_rule r ON r.id = l.rule_id
LEFT JOIN ecom_ad_campaign c ON c.id = l.campaign_id
LEFT JOIN sys_user u ON u.id = l.applied_by

    l.rule_id = #{ruleId}
    AND l.store_id = #{storeId}
    AND l.status = #{status}
    AND l.source = #{source}
    AND l.run_time >= #{begin}
    AND l.run_time < #{end}

        AND (l.entity_name LIKE CONCAT('%', #{keyword}, '%') OR c.name LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY l.run_time DESC, l.id DESC
